/// <reference lib="dom" />
/// <reference lib="dom.iterable" />

import {
  loadFont as loadInter,
  loadFont as loadSans,
} from "@remotion/google-fonts/Inter";
import {
  AbsoluteFill,
  Easing,
  getRemotionEnvironment,
  Interactive,
  type InteractiveBaseProps,
  type InteractiveTransformProps,
  type InteractivitySchema,
  interpolate,
  Sequence,
  type SequenceControls,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import {
  Children,
  cloneElement,
  type ComponentProps,
  createContext,
  type CSSProperties,
  forwardRef,
  isValidElement,
  type ReactElement,
  type ReactNode,
  type Ref,
  useContext,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { converter, formatRgb, parse, type Rgb } from "culori";
import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { loadFont as loadInstrumentSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import { loadFont as loadOutfit } from "@remotion/google-fonts/Outfit";
import { loadFont as loadSpaceGrotesk } from "@remotion/google-fonts/SpaceGrotesk";

/**
 * One object in a scene — a card, a step, a message, a photo — handed to
 * whoever is editing the scene.
 *
 * A scene draws its objects itself: it knows where each one is on every frame.
 * Remotion Studio wants each one as something it can select, outline and edit
 * on its own. `Item` is the seam between the two. The scene wraps the root
 * element of each object in it:
 *
 *   <Item key={i} index={k}>
 *     <div style={…}>…</div>
 *   </Item>
 *
 * With nothing above it — which is every `shadcn add` install and every render
 * on the site — it returns that element untouched: no wrapper, no extra DOM, no
 * behaviour. Inside a Studio Element, an `ItemHost` above it gets the element
 * and the object's index, and can put it inside the object's own `<Sequence>`
 * with the selection outline on that exact node, so the outline moves with the
 * object for its whole animation.
 */
type ItemHost = (index: number, node: ReactElement) => ReactNode;

const ItemHostContext = createContext<ItemHost | null>(null);

const ItemHostProvider = ItemHostContext.Provider;

function Item({
  index,
  primary = true,
  children,
}: {
  /** Which of the scene's objects this is, in the order its props list them. */
  index: number;
  /**
   * False on every copy but one, for a scene that draws the same object more
   * than once (a looping rail): an object has one outline.
   */
  primary?: boolean;
  children: ReactElement;
}): ReactNode {
  const host = useContext(ItemHostContext);
  return host && primary ? host(index, children) : children;
}

const toRgb = converter("rgb");

const BLACK: Rgb = { mode: "rgb", r: 0, g: 0, b: 0, alpha: 1 };

/**
 * Whether to warn. Read through `globalThis`, never a bare `process`: a Vite
 * project defines no `process`, so the bare name threw a ReferenceError on the
 * very input it meant to warn about — and a stock Remotion project has no Node
 * types, so the bare name was also a type error in every install.
 */
function isDev(): boolean {
  const env = (globalThis as { process?: { env?: { NODE_ENV?: string } } })
    .process?.env;
  return env?.NODE_ENV !== "production";
}

function parseColor(c: string): Rgb {
  const s = c.trim();

  if (s.startsWith("var(")) {
    if (isDev()) {
      console.warn(
        `parseColor cannot resolve CSS variable "${s}" under Remotion's per-frame render. ` +
          "Animated colors must be concrete oklch/hex/rgb values supplied via the theme. " +
          "Falling back to the JS default.",
      );
    }
    return { ...BLACK };
  }

  const rgb = toRgb(parse(s));
  if (!rgb) {
    if (isDev()) {
      console.warn(`parseColor could not parse "${s}"; using black.`);
    }
    return { ...BLACK };
  }

  return { mode: "rgb", r: rgb.r, g: rgb.g, b: rgb.b, alpha: rgb.alpha ?? 1 };
}

/**
 * A token at partial opacity — for scrims, veils and inner washes.
 *
 * A scrim written as a literal `rgba(0,0,0,0.4)` is lit for a light surface and
 * does nothing on a dark one; `withAlpha(t.foreground, 0.4)` follows the theme
 * and a user's override. Resolves through `parseColor`, so it inherits the same
 * `var()` guard — an unresolvable token degrades to black rather than an
 * invalid colour string mid-render.
 */
function withAlpha(color: string, alpha: number): string {
  const { r, g, b } = parseColor(color);
  return formatRgb({ mode: "rgb", r, g, b, alpha });
}

/**
 * The type faces a scene's `fontFamily` may name.
 *
 * ## Why an allowlist and not a free string
 *
 * Every component in this registry loads its face through
 * `@remotion/google-fonts` rather than a CSS variable, for the reason spelled
 * out at the top of each one: a Remotion bundle has none of the app's CSS, so
 * `var(--font-…)` gets you the right face in the Player and a **fallback in the
 * mp4**. A bare family name handed to a component has exactly the same problem
 * — the browser preview finds it, the render does not, and the bug is invisible
 * until someone plays the file.
 *
 * So a name only counts as a font here if this module has loaded it. Values map
 * label → the real CSS family string `loadFont` returns, which is not always the
 * label ("Instrument Serif", not "InstrumentSerif").
 *
 * ## A raw stack still works
 *
 * `resolveFont` passes anything it does not recognise straight through, so a
 * caller who has loaded their own face — a brand font, a local `@font-face` —
 * names it directly and gets it. The allowlist is the safe path, not the only one.
 *
 * ponytail: all six load at module scope, so a render fetches six latin subsets
 * whether or not the video uses them. Move to a lazy per-family `loadFont()` if
 * bundle time ever shows up in a render trace.
 */
const FONTS: Record<string, string> = {
  Inter: loadInter("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Geist: loadGeist("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  "Space Grotesk": loadSpaceGrotesk("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Outfit: loadOutfit("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Montserrat: loadMontserrat("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  // 400 is the only weight this family ships. Asking for 600 throws.
  "Instrument Serif": loadInstrumentSerif("normal", {
    weights: ["400"],
    subsets: ["latin"],
  }).fontFamily,
};

/**
 * What a select control offers. `DEFAULT_FONT` first: a scene's own face is a
 * design decision, so the knob has to have an "off", and it has to be the
 * value it ships at.
 */
const DEFAULT_FONT = "Default";

/**
 * Label → loaded CSS family. Anything unrecognised passes through unchanged, so
 * a caller's own stack is never swallowed. `undefined` in, `undefined` out —
 * that is the signal for "keep the component's own face".
 */
const resolveFont = (name?: string): string | undefined =>
  !name || name === DEFAULT_FONT ? undefined : (FONTS[name] ?? name);

interface KitTheme {
  background: string;
  foreground: string;
  card: string;
  cardForeground: string;
  popover: string;
  popoverForeground: string;
  primary: string;
  primaryForeground: string;
  secondary: string;
  secondaryForeground: string;
  muted: string;
  mutedForeground: string;
  accent: string;
  accentForeground: string;
  destructive: string;
  destructiveForeground: string;
  border: string;
  input: string;
  ring: string;
  radius: number;
  /**
   * The face every text component paints with, as a label from `fonts.ts` or a
   * CSS family the caller has loaded themselves.
   *
   * Optional and defaulted to nothing on purpose: unset, each component keeps
   * the face it was designed around, so adding this token changed no existing
   * render. Set it on `KitUIProvider` and one value re-skins a whole
   * timeline — which is the only reason it lives on the theme rather than
   * staying a per-component prop.
   */
  fontFamily?: string;
}

/**
 * The shadcn token set, as concrete values.
 *
 * ## These are a mirror of `app/globals.css`, and that is the whole point
 *
 * A component we ship lands next to somebody's `Button` and `Input`, and those
 * paint from the CSS custom properties in `globals.css`. A scene that paints
 * from a *different* set of greys is a scene that clashes with the app it was
 * installed into — which is exactly what happened here: this file was written
 * first, `globals.css` was later re-skinned warm, and for a while the site and
 * the videos it sells were two different products.
 *
 * So every value below is the **literal string** from the corresponding
 * `--token` in `app/globals.css` (`:root` for light, `.dark` for dark). Hex, not
 * oklch, purely so that drift is a string comparison — if the two files ever
 * disagree again, `pnpm run check:tokens` says so and prints the pairs.
 *
 * ## Why not just read `var(--token)`?
 *
 * Because a Remotion bundle has none of the app's CSS, so `var()` resolves to
 * nothing under the headless renderer and cannot be interpolated by `mixOklch`
 * at all (see the guard in `color.ts`). Concrete values are not a shortcut here,
 * they are the only thing that survives a render. Users on a different palette
 * override via `KitUIProvider` or a component's `theme` prop.
 *
 * ## `radius` is the one value that flows the other way
 *
 * `globals.css` sets `--radius: 0.28rem` *so that* its `--radius-3xl` step lands
 * on this 10 — see the note beside it there. It is not drift; do not "fix" it.
 */
const defaultLightTheme: KitTheme = {
  background: "#faf9f6", // page — warm off-white
  foreground: "#141414", // text
  card: "#ffffff", // surface on the page
  cardForeground: "#141414",
  popover: "#ffffff",
  popoverForeground: "#141414",
  primary: "#3072db", // accent blue
  primaryForeground: "#ffffff",
  secondary: "#f2f0eb", // subtle fill
  secondaryForeground: "#141414",
  muted: "#f2f0eb",
  mutedForeground: "#6e6a63", // secondary text, leading icons
  accent: "#f2f0eb", // hover wash
  accentForeground: "#141414",
  destructive: "#d92d20",
  // `globals.css` defines no --destructive-foreground; white is the only thing
  // that reads on #d92d20, and shadcn's own default agrees.
  destructiveForeground: "#ffffff",
  border: "#d9d9d9", // hairline
  input: "#d9d9d9",
  ring: "#3072db",
  radius: 10,
};

const defaultDarkTheme: KitTheme = {
  background: "#0a0a0b", // page — near-black
  foreground: "#fafafa", // text
  card: "#141417", // surface, a shade above the page
  cardForeground: "#fafafa",
  popover: "#141417",
  popoverForeground: "#fafafa",
  primary: "#3072db", // the same accent blue in both modes
  primaryForeground: "#ffffff",
  secondary: "#1d1d21", // subtle fill
  secondaryForeground: "#fafafa",
  muted: "#1b1b1f",
  mutedForeground: "#a1a1aa", // secondary text, leading icons
  accent: "#1d1d21", // hover wash
  accentForeground: "#fafafa",
  destructive: "#f97066",
  destructiveForeground: "#fafafa",
  border: "#26272b", // hairline — separation is borders, not shadows
  input: "#26272b",
  ring: "#3072db",
  radius: 10,
};

interface KitThemeContextValue {
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
}

const KitThemeContext = createContext<KitThemeContextValue>({});

function useKitTheme(
  override?: Partial<KitTheme>,
  modeOverride?: "light" | "dark",
): KitTheme {
  const ctx = useContext(KitThemeContext);
  const mode = modeOverride ?? ctx.mode ?? "light";
  const base = mode === "dark" ? defaultDarkTheme : defaultLightTheme;
  return { ...base, ...ctx.theme, ...override };
}

// Loaded through @remotion/google-fonts, never a CSS variable — a Remotion
// bundle has none of the app's CSS, so a `var(--font-…)` gets you the right face
// in the Player and a fallback in the mp4 (design-system rule 4).
const { fontFamily: SANS } = loadSans("normal", {
  weights: ["400", "500", "600"],
  subsets: ["latin"],
});

// --- The stage -------------------------------------------------------------
//
// The reference recording is 810×458 — near enough 16:9 — and every number
// below was read off its frames, so there is no second conversion to get wrong.
// `stageScale` fits this rectangle into whatever composition it is given.

const REF_W = 810;
const REF_H = 458;
const EXIT_SCALE = 0.8;
const EXIT_BLUR = 6.5;

/** The entrance eases hard out — half the distance in the first quarter. */
const WORD_EASE = Easing.out(Easing.quad);

// --- Pure helpers (unit-tested) --------------------------------------------

/**
 * The pull-back, as a plain linear scale on the whole tile field.
 *
 * This is the measurement the whole component hangs off. Every tile in the
 * reference shrinks at the *same relative rate* — fit its on-screen size against
 * time and you get a straight line, and dividing that slope by the tile's own
 * size gives 0.176 per second for all seven tiles that are on screen long enough
 * to fit (spread: ±0.0016). Not a perspective dolly — `1/size` is visibly not
 * linear — just one linear scale over a field that is much bigger than the frame.
 */
function pullbackScale(t: number, rate: number, floor = 0.02): number {
  return Math.max(floor, 1 - rate * t);
}

export interface DriftTile {
  /** One to three characters, set large — a mark, not a paragraph. */
  glyph: string;
  /** Optional word under the glyph, for tiles big enough to carry one. */
  label?: string;
  background: string;
  color?: string;
  /** Position at t=0, in stage px from the centre, before the pull-back. */
  x: number;
  y: number;
  /** Edge length at t=0, in stage px, before the pull-back. */
  size: number;
  /** Constant drift, in stage px per second. */
  vx?: number;
  vy?: number;
  /** Seconds at which it starts fading up. */
  at?: number;
  /** Corner radius as a fraction of the tile's edge. Defaults to `tileRadius`. */
  radius?: number;
}

export interface PlacedTile {
  left: number;
  top: number;
  size: number;
  opacity: number;
}

/**
 * Where a tile is, how big, and how far up its fade has got.
 *
 * The field drifts *and* the camera pulls back, and those are two different
 * things: `x + vx·t` is where the tile has got to in the field, and the scale
 * outside it is the camera. Fitted that way, six of the reference's seven
 * long-lived tiles land within **0.3–1.0px per frame across their whole path**;
 * a static field (no drift) misses by 32px, and a perspective dolly cannot
 * produce a size that falls linearly at all.
 */
function placeTile(
  tile: DriftTile,
  t: number,
  o: { rate: number; fade: number; speed: number; scale: number },
): PlacedTile {
  const k = pullbackScale(t, o.rate);
  const wx = tile.x + (tile.vx ?? 0) * o.speed * t;
  const wy = tile.y + (tile.vy ?? 0) * o.speed * t;
  const size = k * tile.size * o.scale;
  const age = t - (tile.at ?? 0);
  // An exponential approach, not a ramp: the reference's tiles are ~50% up
  // 280ms after they appear and still creeping toward 1 a second later, which
  // is the shape a `1 − e^(−age/τ)` gives and no linear fade does.
  const opacity = age <= 0 ? 0 : 1 - Math.exp(-age / Math.max(1e-3, o.fade));
  return {
    left: REF_W / 2 + k * wx - size / 2,
    top: REF_H / 2 + k * wy - size / 2,
    size,
    opacity,
  };
}

export interface WordState {
  scale: number;
  blur: number;
  opacity: number;
}

/**
 * A word's entrance, and the whole line's exit, in one place.
 *
 * The entrance is **not** a fade. Measure the ink and it is conserved from the
 * first frame the word exists — what changes is that it is 1.216× too big and
 * carrying 4.3px of blur, both of which resolve in 140ms. Words land every
 * 150ms, so each one finishes exactly as the next begins.
 */
function wordState(
  t: number,
  index: number,
  o: {
    at: number;
    stagger: number;
    dur: number;
    scale: number;
    blur: number;
    exitAt: number;
    exitDur: number;
    exitScale: number;
    exitBlur: number;
  },
): WordState {
  const start = o.at + index * o.stagger;
  if (t < start) return { scale: o.scale, blur: o.blur, opacity: 0 };
  const p = interpolate(t, [start, start + o.dur], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: WORD_EASE,
  });
  const q = interpolate(t, [o.exitAt, o.exitAt + o.exitDur], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  return {
    scale: (o.scale + (1 - o.scale) * p) * (1 + (o.exitScale - 1) * q),
    blur: o.blur * (1 - p) + o.exitBlur * q,
    opacity: 1 - q,
  };
}

// --- Content ---------------------------------------------------------------

/**
 * The default field: the stack a the library component drops into.
 *
 * Positions, sizes, drifts and entry times are the ones fitted to the reference
 * recording, so the choreography is the measured one. The **labels and the paint
 * are ours** — a component that ships to strangers has no business carrying
 * somebody else's marks, and a wordmark tile says "works with this" without
 * borrowing a logo to say it.
 */
const DEFAULT_STACK: DriftTile[] = [
  {
    glyph: "Rm",
    label: "Remotion",
    background: "#1f2430",
    color: "#ffffff",
    x: 163,
    y: 232,
    vx: -54,
    vy: 12,
    size: 109,
    at: 0.28,
  },
  {
    glyph: "sh",
    label: "shadcn/ui",
    background: "#f2f4f7",
    color: "#16181d",
    x: 128,
    y: -209,
    vx: 81,
    vy: 32,
    size: 122,
    at: 0.48,
  },
  {
    glyph: "Re",
    label: "React",
    background: "#10131a",
    color: "#7dd3fc",
    x: -384,
    y: 344,
    vx: -27,
    vy: -68,
    size: 200,
    at: 0.95,
  },
  {
    glyph: "N",
    label: "Next.js",
    background: "#e7e8ea",
    color: "#16181d",
    x: 519,
    y: 45,
    vx: -31,
    vy: 64,
    size: 144,
    at: 1.51,
  },
  {
    glyph: "tw",
    label: "Tailwind",
    background: "#f1ece2",
    color: "#8a5a2b",
    x: -692,
    y: -125,
    vx: 41,
    vy: -71,
    size: 214,
    at: 1.55,
  },
  {
    glyph: "Fg",
    label: "Figma",
    background: "#2b3a36",
    color: "#ffffff",
    x: -350,
    y: -339,
    vx: 65,
    vy: -26,
    size: 188,
    at: 1.75,
  },
  {
    glyph: "Mo",
    label: "Motion",
    background: "#f4703a",
    color: "#ffffff",
    x: 672,
    y: -277,
    vx: 2,
    vy: 81,
    size: 256,
    at: 1.76,
  },
  {
    glyph: "TS",
    label: "TypeScript",
    background: "#2f6fdb",
    color: "#ffffff",
    x: -721,
    y: 211,
    vx: 9,
    vy: -84,
    size: 215,
    at: 2.06,
  },
  {
    glyph: "▲",
    label: "Vercel",
    background: "#0b0b0d",
    color: "#ffffff",
    x: 676,
    y: 348,
    vx: -65,
    vy: 52,
    size: 244,
    at: 2.48,
  },
];

// --- Props -----------------------------------------------------------------

export interface LogoDriftProps {
  /** The line that writes itself, one word at a time. */
  headline?: string;
  /** The field. Positions are stage px from the centre, before the pull-back. */
  tiles?: DriftTile[];

  // --- Motion, in seconds and per-second rates. ---
  /** How fast the camera pulls back, as a fraction of scale per second. */
  pullback?: number;
  /** Multiplies every tile's drift, and every tile's size. */
  tileSpeed?: number;
  tileScale?: number;
  /** Time constant of a tile's fade-up. */
  tileFade?: number;
  /** Corner radius as a fraction of a tile's edge. */
  tileRadius?: number;

  /** When the first word lands, and the gap between words. */
  wordAt?: number;
  wordStagger?: number;
  /** How long one word takes to land, and what it arrives as. */
  wordDuration?: number;
  wordScale?: number;
  wordBlur?: number;

  /** When the line leaves, over how long, and what it leaves as. */
  exitAt?: number;
  exitDuration?: number;
  exitScale?: number;
  exitBlur?: number;

  // --- Size and paint. ---
  /** Headline type size, in stage px. */
  fontSize?: number;
  fontWeight?: number;
  /** Glyph size inside a tile, as a fraction of its edge. */
  glyphScale?: number;
  /** Show the soft wash behind the headline, and what colour it is. */
  glow?: boolean;
  glowColor?: string;
  glowOpacity?: number;
  /** Accent used for the wash when `glowColor` is not given. */
  accentColor?: string;
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
  /**
   * The face this scene paints its words in — a label from `fonts.ts`
   * ("Inter", "Space Grotesk", "Instrument Serif") or a CSS family you have
   * loaded yourself. Unset, the scene keeps the face it was designed around.
   *
   * Overrides `theme.fontFamily`, which is how a brand kit re-skins a whole
   * timeline from one value.
   */
  fontFamily?: string;
  speed?: number;
}

// --- Main composition ------------------------------------------------------

/**
 * A field of tiles drifting past a headline while the camera pulls steadily
 * back, so the wall of things-it-works-with keeps arriving from every edge.
 *
 * ## Three measurements, and they are the component
 *
 * **The pull-back is one linear scale.** Every tile in the reference shrinks at
 * the same *relative* rate: fit on-screen size against time and it is a straight
 * line, and dividing the slope by the tile's own size gives **0.176 per second**
 * for every tile long enough to fit, to ±0.0016. It is not a perspective dolly —
 * under perspective `1/size` would be the straight line and it plainly is not.
 *
 * **The field drifts under it.** Take the scale out and each tile's path becomes
 * a straight world-line to within a pixel: a constant velocity, ~80 stage px per
 * second, in its own direction. Model it as a static field and you are 32px out;
 * model the drift and six of the seven fitted tiles land within **0.3–1.0px per
 * frame over their whole path**.
 *
 * **The words do not fade in.** Measure the ink and it is conserved from the
 * first frame a word exists. What resolves is 1.216× of scale and 4.3px of blur,
 * in 140ms, one word every 150ms — so each lands exactly as the next starts. The
 * line is centre-set, so the words already placed slide left to make room.
 *
 * ## What is not measured
 *
 * The labels and the paint. The reference is a specific product showing off a
 * specific set of other people's logos; none of that belongs in a component that
 * ships to strangers (design-system rule 5). The default field is the stack a
 * the library component actually drops into, drawn as wordmark tiles rather than
 * borrowed marks, and every tile — glyph, label, colour, position, drift, entry
 * — is a prop.
 */
function LogoDriftScene({
  headline = "Built for the stack you already use.",
  tiles = LogoDriftDefaults.tiles,
  pullback = 0.1762,
  tileSpeed = 1,
  tileScale = 1,
  tileFade = 0.4,
  tileRadius = 0.02,
  wordAt = 0.017,
  wordStagger = 0.15,
  wordDuration = 0.14,
  wordScale = 1.216,
  wordBlur = 4.3,
  exitAt = 3.13,
  exitDuration = 0.34,
  exitScale = EXIT_SCALE,
  exitBlur = EXIT_BLUR,
  fontSize = 20,
  fontWeight = 500,
  glyphScale = 0.34,
  glow = false,
  glowColor,
  glowOpacity = 0.07,
  accentColor,
  theme,
  mode,
  fontFamily,
  speed = 1,
}: LogoDriftProps) {
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();
  const t = useKitTheme(theme, mode);
  const face = resolveFont(fontFamily ?? t.fontFamily) ?? SANS;
  const accent = accentColor ?? t.primary;
  const wash = glowColor ?? accent;

  const now = (frame * speed) / fps;
  const stageScale = Math.min(width / REF_W, height / REF_H);

  const words = headline.split(/\s+/).filter(Boolean);
  const isRendering = getRemotionEnvironment().isRendering;
  const willChange = isRendering ? undefined : ("transform, filter" as const);

  return (
    <AbsoluteFill showInTimeline={false} style={{ background: t.background }}>
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          width: REF_W,
          height: REF_H,
          transform: `translate(-50%, -50%) scale(${stageScale})`,
          overflow: "hidden",
          background: t.background,
        }}
      >
        {/* The wash. Static — it does not move, breathe or follow the pull-back
            on the reference, and a glow that animates under a headline reads as
            a mistake rather than as light. Painted from the installer's accent
            at a few percent, because at this strength it is a tint, not a shape:
            the peak is seven luminance levels off the page. */}
        {glow ? (
          <div
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              width: REF_W,
              height: REF_H,
              background: `radial-gradient(${0.45 * REF_W}px ${0.34 * REF_H}px at 50% 49%, ${withAlpha(wash, glowOpacity)} 0%, transparent 74%)`,
            }}
          />
        ) : null}

        {/* ---- The field. Each tile is one object to Remotion Studio (`Item`),
            numbered by its place in `tiles`. */}
        {tiles.map((tile, i) => {
          const p = placeTile(tile, now, {
            rate: pullback,
            fade: tileFade,
            speed: tileSpeed,
            scale: tileScale,
          });
          if (p.opacity <= 0.002 || p.size < 1) return null;
          const fg = tile.color ?? t.background;
          return (
            <Item key={`${tile.glyph}-${tile.x}-${tile.y}`} index={i}>
              <div
                style={{
                  position: "absolute",
                  left: p.left,
                  top: p.top,
                  width: p.size,
                  height: p.size,
                  borderRadius: p.size * (tile.radius ?? tileRadius),
                  background: tile.background,
                  opacity: p.opacity,
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  justifyContent: "center",
                  gap: p.size * 0.04,
                  color: fg,
                  fontFamily: face,
                  overflow: "hidden",
                  willChange,
                }}
              >
                <span
                  style={{
                    fontSize: p.size * glyphScale,
                    fontWeight: 600,
                    lineHeight: 1,
                    letterSpacing: "-0.03em",
                    textRendering: "geometricPrecision",
                  }}
                >
                  {tile.glyph}
                </span>
                {tile.label && p.size > 74 ? (
                  <span
                    style={{
                      fontSize: p.size * 0.1,
                      fontWeight: 500,
                      lineHeight: 1,
                      opacity: 0.72,
                      textRendering: "geometricPrecision",
                    }}
                  >
                    {tile.label}
                  </span>
                ) : null}
              </div>
            </Item>
          );
        })}

        {/* ---- The headline. Above the field: a wall of logos that crosses the
            one line the viewer is meant to read is a wall of logos that has won
            an argument it should not have been in. */}
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: REF_W,
            height: REF_H,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "baseline",
              justifyContent: "center",
              gap: fontSize * 0.28,
              fontFamily: face,
              fontSize,
              fontWeight,
              lineHeight: 1.2,
              letterSpacing: "-0.012em",
              color: t.foreground,
              whiteSpace: "pre",
              textRendering: "geometricPrecision",
            }}
          >
            {words.map((word, i) => {
              const w = wordState(now, i, {
                at: wordAt,
                stagger: wordStagger,
                dur: wordDuration,
                scale: wordScale,
                blur: wordBlur,
                exitAt,
                exitDur: exitDuration,
                exitScale,
                exitBlur,
              });
              return (
                <span
                  // biome-ignore lint/suspicious/noArrayIndexKey: words in a headline repeat, so the index is what makes each key unique
                  key={`${word}-${i}`}
                  style={{
                    display: "inline-block",
                    opacity: w.opacity,
                    transform: `scale(${w.scale})`,
                    filter: w.blur > 0.02 ? `blur(${w.blur}px)` : undefined,
                    willChange,
                  }}
                >
                  {word}
                </span>
              );
            })}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
}

/* ─────────────────────────────────────────────────────────────────────────
   Remotion Studio: one tile at a time
   ───────────────────────────────────────────────────────────────────────── */

/**
 * Everything `el` paints that can be seen, in page pixels: its text runs, its
 * media, and every box with a fill or a border, each cut to every box that
 * clips it up to and including `root` (the Element's own box). Null when none
 * of it shows — transparent, or clipped out of the Element.
 */
function LogoDriftPainted(
  el: Element,
  root: Element,
): [number, number, number, number] | null {
  let u: [number, number, number, number] | null = null;
  const add = (r: DOMRect, from: Element) => {
    // Never past the Element's own box, clipped or not: a text run's line box
    // stands above its ink, and no scene's ink leaves its box (measured).
    const c0 = root.getBoundingClientRect();
    let b: [number, number, number, number] = [
      Math.max(r.left, c0.left),
      Math.max(r.top, c0.top),
      Math.min(r.right, c0.right),
      Math.min(r.bottom, c0.bottom),
    ];
    let alpha = 1;
    for (
      let a: Element | null = from;
      a;
      a = a === root ? null : a.parentElement
    ) {
      const cs = getComputedStyle(a);
      if (cs.visibility === "hidden") return;
      alpha *= Number(cs.opacity);
      if (a !== from && a !== root && cs.overflow !== "visible") {
        const c = a.getBoundingClientRect();
        b = [
          Math.max(b[0], c.left),
          Math.max(b[1], c.top),
          Math.min(b[2], c.right),
          Math.min(b[3], c.bottom),
        ];
      }
    }
    if (alpha < 0.02 || b[2] <= b[0] || b[3] <= b[1]) return;
    u = u
      ? [
          Math.min(u[0], b[0]),
          Math.min(u[1], b[1]),
          Math.max(u[2], b[2]),
          Math.max(u[3], b[3]),
        ]
      : b;
  };
  const walk = (e: Element) => {
    const cs = getComputedStyle(e);
    if (cs.display === "none") return;
    const media = /^(img|video|canvas|svg)$/i.test(e.tagName);
    if (
      media ||
      cs.backgroundColor !== "rgba(0, 0, 0, 0)" ||
      cs.backgroundImage !== "none" ||
      parseFloat(cs.borderTopWidth) > 0
    )
      add(e.getBoundingClientRect(), e);
    if (media) return;
    for (const n of Array.from(e.childNodes)) {
      if (n.nodeType === Node.TEXT_NODE && n.textContent?.trim()) {
        const range = document.createRange();
        range.selectNodeContents(n);
        for (const r of Array.from(range.getClientRects())) add(r, e);
      } else if (n.nodeType === Node.ELEMENT_NODE) walk(n as Element);
    }
  };
  walk(el);
  return u;
}

/** Whether every box that clips `el`, up to `root`, leaves all of it showing. */
function LogoDriftWhole(el: Element, root: Element): boolean {
  const r = el.getBoundingClientRect();
  for (let a = el.parentElement; a; a = a === root ? null : a.parentElement) {
    if (getComputedStyle(a).overflow === "visible") continue;
    const c = a.getBoundingClientRect();
    if (
      r.left < c.left - 1 ||
      r.top < c.top - 1 ||
      r.right > c.right + 1 ||
      r.bottom > c.bottom + 1
    )
      return false;
  }
  return true;
}
type LogoDriftTileValues = {
  readonly glyph?: string;
  readonly label?: string;
};

type LogoDriftTileProps = InteractiveBaseProps &
  Omit<InteractiveTransformProps, "style"> &
  LogoDriftTileValues & {
    readonly style?: CSSProperties | null;
    /** The node the scene draws this tile as, while it draws it; set by the stage, never by hand. */
    readonly claim?: { current: Element | null };
    /** The box its outline falls back to when the node is not all there; set by the stage too. */
    readonly slot?: { current: HTMLDivElement | null };
    /** Hands Studio's live props back to the stage, which draws the node; set by the stage too. */
    readonly report?: (state: LogoDriftTileState) => void;
  };

/** What Studio is doing to one tile right now, which the stage applies to its node. */
type LogoDriftTileState = {
  values: LogoDriftTileValues;
  style?: CSSProperties;
  hidden?: boolean;
  from?: number;
  durationInFrames?: number;
};

const LogoDriftTileSchema = {
  ...Interactive.baseSchema,
  glyph: { type: "text-content", default: "", description: "Glyph" },
  label: { type: "text-content", default: "", description: "Label" },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

/**
 * One tile: its layer in Studio. The scene decides where it is on every
 * frame and draws it; this is the Sequence Studio lists, selects and outlines,
 * mounted for the Element's whole length so the layer never leaves the
 * timeline while the tile is off the frame. It draws nothing itself: its
 * values, transform, visibility and timing reach the node through the stage.
 */
const LogoDriftTileInner = forwardRef<
  Element,
  LogoDriftTileProps & { readonly controls: SequenceControls | undefined }
>(
  (
    {
      controls,
      name,
      style,
      from,
      durationInFrames,
      trimBefore,
      playbackRate,
      loop,
      freeze,
      hidden,
      showInTimeline,
      claim,
      slot,
      report,
      glyph,
      label,
    },
    ref,
  ) => {
    // What Studio outlines, chosen every frame: the node itself — its exact
    // quad, transforms and all — while all of it shows; a box over the part
    // that does when the Element clips it or it paints past its own box; nothing while none of it
    // shows, so an object that has left is not still selectable where it was.
    const target = useRef<Element | null>(null);
    // Re-rendered every frame, so the outline is chosen for every frame: the
    // scene moves the node without re-rendering this layer.
    useCurrentFrame();
    // Studio reads the ref every time it measures.
    const outline = useRef({
      get current() {
        return target.current ?? claim?.current ?? null;
      },
    }).current;
    // Studio's live props arrive here — a value being typed, a transform being
    // dragged, the layer hidden or retimed — and the stage draws the node.
    useLayoutEffect(() => {
      report?.({
        values: { glyph, label },
        style: style ?? undefined,
        hidden,
        from,
        durationInFrames,
      });
    });
    useImperativeHandle(ref, () => claim?.current as Element);
    useLayoutEffect(() => {
      // Outlines are a Studio thing; a render or the Player measures nothing.
      if (!getRemotionEnvironment().isStudio) return;
      const box = slot?.current;
      const root = box?.parentElement;
      if (!box || !root) return;
      const el = claim?.current;
      const b = el ? LogoDriftPainted(el, root) : null;
      if (!el || !b) {
        box.style.display = "none";
        target.current = box;
        return;
      }
      const n = el.getBoundingClientRect();
      if (
        LogoDriftWhole(el, root) &&
        b[0] >= n.left - 1 &&
        b[1] >= n.top - 1 &&
        b[2] <= n.right + 1 &&
        b[3] <= n.bottom + 1
      ) {
        box.style.display = "none";
        target.current = el;
        return;
      }
      const r = root.getBoundingClientRect();
      const k = root.offsetWidth / (r.width || 1);
      box.style.display = "block";
      box.style.left = `${(b[0] - r.left) * k}px`;
      box.style.top = `${(b[1] - r.top) * k}px`;
      box.style.width = `${(b[2] - b[0]) * k}px`;
      box.style.height = `${(b[3] - b[1]) * k}px`;
      target.current = box;
    });
    return (
      <Sequence
        layout="none"
        from={from}
        durationInFrames={durationInFrames}
        trimBefore={trimBefore}
        playbackRate={playbackRate}
        loop={loop}
        freeze={freeze}
        hidden={hidden}
        showInTimeline={showInTimeline}
        name={name ?? "Tile"}
        controls={controls}
        outlineRef={outline}
      />
    );
  },
);

